@import "tailwindcss" source(none);
@source "./**/*.{ts,tsx}";
@source "../components/**/*.{ts,tsx}";

/* Preserve migrated CSS :hover behavior, including touch-emulated hover. */
@custom-variant css-hover (&:hover);
@custom-variant mono (:where(html[data-appearance="vercel"]) &);
@custom-variant workspace-mono (:where(html[data-workspace][data-appearance="vercel"]) &);

:root {
  color-scheme: light;
  --background: var(--color-globals-background-1);
  --surface: var(--color-globals-surface-2);
  --card: var(--color-globals-card-3);
  --foreground: var(--color-globals-foreground-4);
  --muted-foreground: var(--color-globals-muted-foreground-5);
  --border: color-mix(
    in srgb,
    var(--accent) 30%,
    var(--color-globals-border-6)
  );
  --border-hover: color-mix(in srgb, var(--accent) 55%, var(--card));
  --accent: var(--color-globals-accent-7);
  --accent2: var(--color-globals-accent2-8);
  --accent-soft: var(--color-globals-accent-soft-9);
  --logo-background: linear-gradient(
    135deg,
    var(--color-globals-accent-7),
    var(--color-globals-logo-background-10)
  );
  --logo-ink: var(--color-globals-card-3);
  --avatar-background: linear-gradient(
    135deg,
    var(--color-globals-accent-7),
    var(--color-globals-avatar-background-11)
  );
  --scrollbar-thumb: color-mix(in srgb, var(--accent) 35%, var(--background));
  --scrollbar-track: var(--background);
  --success: var(--color-globals-success-12);
  --replied: var(--color-globals-replied-13);
  --queued: var(--color-globals-queued-14);
  --error: var(--color-globals-error-15);
  --shadow: 0 8px 30px var(--color-globals-shadow-16);
  --on-accent: var(--color-globals-foreground-4);
  --primary-foreground: var(--color-globals-card-3);
  --status-success-text: color-mix(
    in srgb,
    var(--success) 65%,
    var(--foreground)
  );
  --status-replied-text: color-mix(
    in srgb,
    var(--replied) 65%,
    var(--foreground)
  );
  --status-warning-text: var(--color-globals-status-warning-text-17);
  --status-error-text: color-mix(in srgb, var(--error) 65%, var(--foreground));
  --link: color-mix(in srgb, var(--accent) 85%, var(--foreground));
  --primary: var(--accent);
  --muted: var(--surface);
  --body: var(--muted-foreground);
  --premium-notice-background: var(
    --color-globals-premium-notice-background-18
  );
  --premium-notice-border: var(--color-globals-premium-notice-border-19);
  --premium-notice-text: var(--color-globals-status-warning-text-17);
  --control-border: var(--border);
  --ring: var(--accent);
  --destructive: var(--status-error-text);
  --warning: var(--status-warning-text);
  --warning-soft: var(--color-globals-premium-notice-background-18);
  --button-foreground: var(--primary-action-ink);
  --button-start: var(--color-globals-button-start-20);
  --button-end: var(--color-globals-button-end-21);
  --button-glow: 16%;
  --button-glow-hover: 23%;
  --ring-track: var(--color-globals-ring-track-22);
  --placeholder-background: var(--color-globals-placeholder-background-23);
  --placeholder-foreground: var(--color-globals-placeholder-foreground-24);
  --skeleton-base: color-mix(in srgb, var(--accent) 9%, var(--surface));
  --skeleton-highlight: color-mix(in srgb, var(--card) 65%, transparent);
  --accent-gradient: linear-gradient(135deg, var(--accent), var(--accent2));
  --button-gradient: var(--primary-action-gradient);
}
[data-theme="dark"] {
  color-scheme: dark;
  --primary-foreground: var(--on-accent);
  --premium-notice-background: var(
    --color-globals-premium-notice-background-25
  );
  --premium-notice-border: var(--color-globals-premium-notice-border-26);
  --premium-notice-text: var(--color-globals-premium-notice-text-27);
  --background: var(--color-globals-background-28);
  --surface: var(--color-globals-surface-29);
  --card: var(--color-globals-card-30);
  --foreground: var(--color-globals-foreground-31);
  --muted-foreground: var(--color-globals-muted-foreground-32);
  --border: color-mix(
    in srgb,
    var(--accent) 40%,
    var(--color-globals-border-33)
  );
  --accent: var(--color-globals-accent-34);
  --accent2: var(--color-globals-accent2-35);
  --accent-soft: var(--color-globals-accent-soft-36);
  --logo-background: var(--accent-gradient);
  --logo-ink: var(--color-globals-foreground-4);
  --avatar-background: linear-gradient(
    135deg,
    color-mix(in srgb, var(--accent) 80%, var(--on-accent)),
    color-mix(in srgb, var(--accent) 60%, var(--on-accent))
  );
  --success: var(--color-globals-success-37);
  --replied: var(--color-globals-replied-38);
  --queued: var(--color-globals-queued-39);
  --status-warning-text: color-mix(
    in srgb,
    var(--queued) 55%,
    var(--foreground)
  );
  --warning-soft: color-mix(in srgb, var(--queued) 15%, transparent);
  --error: var(--color-globals-error-40);
  --shadow: 0 8px 40px var(--color-globals-shadow-41);
  --button-foreground: var(--primary-action-ink);
  --button-start: var(--accent);
  --button-end: var(--accent2);
  --button-glow: 24%;
  --button-glow-hover: 32%;
  --ring-track: var(--color-globals-ring-track-42);
  --placeholder-background: var(--color-globals-placeholder-background-43);
  --placeholder-foreground: var(--color-globals-placeholder-foreground-44);
  --skeleton-highlight: color-mix(in srgb, var(--accent) 14%, transparent);
}
html {
  scroll-behavior: smooth;
}
html,
* {
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
}
@supports not (scrollbar-color: auto) {
  @media (forced-colors: none) {
    ::-webkit-scrollbar-thumb {
      background-color: var(--scrollbar-thumb);
    }
    ::-webkit-scrollbar-track,
    ::-webkit-scrollbar-corner {
      background-color: var(--scrollbar-track);
    }
  }
}
@media (forced-colors: active) {
  html,
  * {
    scrollbar-color: auto;
  }
}
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-border: var(--border);
  --color-separator: var(--separator);
  --color-control-border: var(--control-border);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);
  --color-body: var(--body);
  --color-link: var(--link);
  --color-error-deep: var(--destructive);
  --color-warning: var(--warning);
  --color-warning-soft: var(--warning-soft);
  --font-sans: var(--font-plus-jakarta), system-ui, sans-serif;
  --font-mono: var(--font-jetbrains), monospace;
  --font-num: var(--font-space-grotesk), system-ui, sans-serif;
  --radius-sm: 12px;
  --radius-md: 12px;
  --radius-lg: 20px;
}
.contact-form input {
  --contact-input-background: var(--surface);
}
.contact-form input[data-previously-emailed="true"] {
  --contact-input-background: color-mix(
    in srgb,
    var(--queued) 15%,
    var(--surface)
  );
  background-color: var(--contact-input-background);
  border-color: var(--warning);
}
.contact-form input[data-slot="input"]:autofill,
.contact-form input[data-slot="input"]:autofill:focus-visible {
  box-shadow: inset 0 0 0 1000px var(--contact-input-background);
  -webkit-text-fill-color: var(--foreground);
  caret-color: var(--foreground);
}
.contact-form input[data-slot="input"]:-webkit-autofill,
.contact-form input[data-slot="input"]:-webkit-autofill:focus-visible {
  box-shadow: inset 0 0 0 1000px var(--contact-input-background);
  -webkit-text-fill-color: var(--foreground);
  caret-color: var(--foreground);
}
@layer base {
  body {
    background:
      radial-gradient(
        900px 400px at 85% -10%,
        color-mix(in srgb, var(--accent) 18%, transparent),
        transparent
      ),
      var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 14px;
    line-height: 1.5;
  }
  button,
  a,
  input,
  select,
  textarea,
  summary {
    -webkit-tap-highlight-color: transparent;
  }
  button,
  a,
  summary {
    touch-action: manipulation;
  }
  a.text-link {
    text-decoration: underline;
    text-underline-offset: 3px;
  }
  a.text-link:hover {
    color: var(--foreground);
  }
  a:focus-visible,
  [tabindex]:focus-visible,
  summary:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 4px;
  }
  h1,
  h2,
  h3 {
    text-wrap: balance;
  }
  h1 {
    font-weight: 700;
    letter-spacing: -0.03em;
  }
  p {
    text-wrap: pretty;
  }
  select {
    min-height: 44px;
    max-width: 100%;
    border: 1px solid var(--control-border);
    border-radius: 12px;
    padding: 8px 12px;
    background: var(--surface);
    color: var(--foreground);
  }
  select:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: var(--primary);
  }
  input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }
  th {
    text-align: left;
    font-weight: 500;
    color: var(--body);
  }
  th,
  td {
    padding: 16px 24px;
    border-bottom: 1px dotted var(--separator);
  }
  dialog {
    background: var(--card);
    color: var(--foreground);
    border: 1px solid var(--border);
    border-radius: 12px;
    margin: auto;
    padding: 24px;
    max-width: min(480px, calc(100vw - 32px));
    overscroll-behavior: contain;
  }
  dialog::backdrop {
    background: color-mix(in srgb, var(--on-accent) 35%, transparent);
  }
}
@utility page-container {
  width: 100%;
  max-width: 1120px;
  margin-inline: auto;
  padding-left: max(20px, env(safe-area-inset-left));
  padding-right: max(20px, env(safe-area-inset-right));
}
@utility panel {
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--card);
  box-shadow: var(--shadow);
}
@utility eyebrow {
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 16px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--body);
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

@theme inline {
  --color-surface: var(--surface);
  --color-accent-soft: var(--accent-soft);
  --color-success: var(--status-success-text);
}
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}
html[data-theme-reveal]::view-transition,
html[data-appearance-transition]::view-transition {
  pointer-events: none;
}
html[data-theme-reveal]::view-transition-image-pair(root) {
  isolation: auto;
}
html[data-theme-reveal]::view-transition-old(root) {
  z-index: 1;
}
html[data-theme-reveal]::view-transition-new(root) {
  z-index: 2;
  clip-path: circle(0px at var(--theme-reveal-origin));
}
html :is(.primary-button, .primary-action, .upgrade-shine) {
  --button-hover-filter: none;
}
/* A 2s round trip followed by 4s at rest, behind the label and clipped. */
.upgrade-shine::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(
    105deg,
    transparent 46%,
    var(--upgrade-shine) 50%,
    transparent 54%
  );
  transform: translateX(-110%);
  animation: premium-button-shine 6s ease-in-out 3s infinite;
}
@keyframes premium-button-shine {
  0%,
  33.333333%,
  100% {
    transform: translateX(-110%);
  }
  16.666667% {
    transform: translateX(110%);
  }
}
.upgrade-shine:is(
    :disabled,
    [aria-disabled="true"],
    [aria-busy="true"]
  )::before {
  display: none;
  animation: none;
}
@media (prefers-reduced-motion: reduce) {
  .upgrade-shine::before {
    display: none;
    animation: none;
  }
}
.skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 15%,
    var(--skeleton-highlight) 50%,
    transparent 85%
  );
  transform: translateX(-100%);
  animation: skeleton-shimmer 1.8s ease-in-out infinite;
}
@keyframes skeleton-shimmer {
  to {
    transform: translateX(100%);
  }
}
.page-transition {
  animation: page-enter 220ms ease-out;
}
@keyframes page-enter {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
:where(
  .panel,
  .mail-preview,
  .workspace-nav,
  .theme-track,
  .chip,
  .border.border-border,
  .border.border-control-border,
  select,
  dialog
) {
  transition: border-color 150ms ease;
}
@media (hover: hover) {
  :where(
      .panel,
      .mail-preview,
      .workspace-nav,
      .theme-track,
      .chip,
      .border.border-border,
      .border.border-control-border,
      select,
      dialog
    ):hover:where(:not(:disabled):not([aria-invalid="true"])) {
    border-color: var(--border-hover);
  }
}
:where(
  .panel,
  .mail-preview,
  .workspace-nav,
  .theme-track,
  .border.border-border,
  dialog
):focus-within,
.chip:focus-visible,
.border.border-control-border:focus-visible:not([aria-invalid="true"]):not(
    :is(input, select, textarea)
  ) {
  border-color: var(--accent);
}
/* Only the innermost hovered card lifts; controls and skeletons stay still. */
:is(
  .panel,
  .mail-preview,
  .hover-card,
  .recipient-card,
  .send-checklist,
  .landing-glow-card,
  .landing-closing
) {
  transition:
    transform 350ms cubic-bezier(0.2, 0.8, 0.2, 1),
    background-color 350ms ease,
    border-color 350ms ease,
    box-shadow 350ms ease;
}
@media (hover: hover) {
  :is(
      .panel,
      .mail-preview,
      .hover-card,
      .recipient-card,
      .send-checklist,
      .landing-glow-card
    ):hover:not([aria-hidden="true"]):not([aria-hidden="true"] *):not(
      :has(.skeleton)
    ):not(
      :has(
        :is(
          .panel,
          .mail-preview,
          .hover-card,
          .recipient-card,
          .send-checklist,
          .landing-glow-card,
          .landing-closing
        ):hover
      )
    ) {
    transform: translateY(-6px);
    border-color: var(--card-hover-accent, var(--accent));
    box-shadow:
      0 0 0 1px
        color-mix(
          in srgb,
          var(--card-hover-accent, var(--accent))
            calc(45% * var(--batch-shadow-scale, 1)),
          transparent
        ),
      0 14px 44px -10px
        color-mix(
          in srgb,
          var(--card-hover-accent, var(--accent))
            calc(50% * var(--batch-shadow-scale, 1)),
          transparent
        ),
      0 0 30px
        color-mix(
          in srgb,
          var(--card-hover-secondary, var(--accent2))
            calc(14% * var(--batch-shadow-scale, 1)),
          transparent
        ),
      inset 0 0 40px
        color-mix(
          in srgb,
          var(--card-hover-accent, var(--accent))
            calc(10% * var(--batch-shadow-scale, 1)),
          transparent
        );
  }
}
@media (prefers-reduced-motion: reduce) {
  .campaign-progress-stat {
    transition: none;
  }
  :is(
    .panel,
    .mail-preview,
    .hover-card,
    .recipient-card,
    .send-checklist,
    .landing-glow-card,
    .landing-batch,
    .landing-stat,
    .landing-closing
  ) {
    transform: none !important;
  }
}
.theme-track button {
  width: 44px;
  height: 44px;
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  border-radius: 999px;
  color: var(--body);
  cursor: pointer;
}
.theme-track button[aria-pressed="true"] {
  color: var(--primary-foreground);
}
.theme-track svg {
  width: 18px;
  height: 18px;
}
.theme-thumb {
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
[data-theme="dark"] .theme-thumb {
  transform: translateX(44px);
}
:root {
  --nav-bg: var(--color-nav-lavender-bg);
  --nav-line: var(--color-nav-lavender-line);
  --nav-active-bg: var(--color-nav-lavender-active-bg);
  --nav-active-line: var(--color-nav-lavender-active-line);
  --nav-active-ink: var(--color-nav-lavender-active-ink);
  --nav-muted: var(--color-nav-lavender-muted);
  --nav-hover: var(--color-nav-lavender-hover);
}
[data-theme="dark"] {
  --nav-bg: var(--color-nav-nightbloom-bg);
  --nav-line: var(--color-nav-nightbloom-line);
  --nav-active-bg: var(--color-nav-nightbloom-active-bg);
  --nav-active-line: var(--color-nav-nightbloom-active-line);
  --nav-active-ink: var(--color-nav-nightbloom-active-ink);
  --nav-muted: var(--color-nav-nightbloom-muted);
  --nav-hover: var(--color-nav-nightbloom-hover);
}
html[data-appearance="vercel"] {
  --nav-bg: var(--card);
  --nav-line: var(--border);
}
.workspace-nav::-webkit-scrollbar {
  display: none;
}
.workspace-nav a {
  transition:
    color 0.2s,
    background-color 0.2s,
    gap 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
.workspace-nav-highlight {
  transition:
    transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    width 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    height 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
.workspace-nav a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.workspace-nav a:hover {
  color: var(--foreground);
}
.workspace-nav a:not([aria-current]):hover {
  background: var(--nav-hover);
}
.workspace-nav a[aria-current="page"] {
  color: var(--nav-active-ink);
}
.workspace-nav:not([data-highlight-ready]) a[aria-current="page"] {
  background: var(--nav-active-bg);
  outline: 1px solid var(--nav-active-line);
  outline-offset: -1px;
}
.workspace-nav:not([data-highlight-ready])
  a[aria-current="page"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
@container (max-width: 600px) {
  .workspace-nav-label {
    display: grid;
    grid-template-columns: 1fr;
    opacity: 1;
    transition:
      grid-template-columns 0.32s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.2s;
  }
  .workspace-nav-label > span {
    overflow: hidden;
    min-width: 0;
  }
  .workspace-nav a:not([aria-current="page"]) .workspace-nav-label {
    grid-template-columns: 0fr;
    opacity: 0;
  }
  .workspace-nav a:not([aria-current="page"]) {
    gap: 0;
  }
  .workspace-nav a {
    padding-inline: 0.85em;
  }
}
@container (max-width: 600px) {
  .workspace-nav-placeholder:not(:first-child) {
    width: 2.85em;
  }
}
@media (forced-colors: active) {
  .workspace-nav a[aria-current="page"] {
    outline: 1px solid LinkText;
    outline-offset: -1px;
  }
}
.compose-grid > *,
.template-grid > *,
main section {
  min-width: 0;
}
.placeholder-chip {
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}
.placeholder-chip:hover:not(:disabled) {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, var(--accent-soft));
}
/* Only message content scrolls; recipient, subject, and feedback stay outside. */
.mail-preview-body ul,
.mail-preview-body ol {
  margin: 0;
  padding-left: 24px;
  white-space: normal;
}
.mail-preview-body ul {
  list-style: disc;
}
.mail-preview-body ol {
  list-style: decimal;
}
.mail-preview-body li {
  white-space: pre-wrap;
}
.mail-preview mark {
  background: var(--placeholder-background);
  color: var(--placeholder-foreground);
  padding: 0 4px;
  border-radius: 5px;
}
.mail-preview mark.invalid {
  background: color-mix(in srgb, var(--error) 15%, transparent);
  color: var(--status-error-text);
  outline: 1px dashed var(--error);
}
[data-theme="dark"] .status-sent {
  color: var(--color-globals-color-50);
  background: color-mix(
    in srgb,
    var(--color-globals-background-49) 12%,
    transparent
  );
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--color-globals-background-49) 24%, transparent);
}
[data-theme="dark"] .status-replied {
  color: var(--color-globals-replied-38);
  background: color-mix(
    in srgb,
    var(--color-globals-background-52) 12%,
    transparent
  );
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--color-globals-background-52) 24%, transparent);
}
.live-dot,
