  }
}

/* Keep History readable without letting row actions dictate its height. */
.history-actions > div {
  max-width: 100%;
}
.history-actions button {
  height: auto;
  max-width: 100%;
  white-space: normal;
  padding: 8px 10px;
}

/* Native browser presentation follows the selected workspace palette. */
html[data-themed] {
  accent-color: var(--ring);
  caret-color: var(--foreground);
}
html[data-themed] ::selection {
  background: var(--accent);
  color: var(--button-foreground);
  -webkit-text-fill-color: var(--button-foreground);
}
html[data-themed] input:autofill {
  -webkit-text-fill-color: var(--foreground);
  box-shadow: inset 0 0 0 1000px var(--surface);
}

/* Field feedback changes paint only; the native caret and text layout stay immediate. */
html
  :is(
    input:not(
      [type="checkbox"],
      [type="radio"],
      [type="file"],
      [type="range"],
      [type="color"],
      [type="hidden"],
      [type="button"],
      [type="submit"],
      [type="reset"],
      [type="image"]
    ),
    textarea,
    select
  ) {
  caret-color: var(--foreground);
  transition:
    border-color 150ms ease,
    background-color 150ms ease,
    box-shadow 150ms ease;
}
html :where(input, textarea, select):is([aria-invalid="true"], :user-invalid) {
  border-color: var(--destructive);
}

/* A press responds on touch and keyboard too, without changing button geometry. */
:is(button, [role="button"], .button-interaction, .landing-button):active:not(
    :disabled
  ):not([aria-disabled="true"]):not([aria-busy="true"]) {
  scale: 0.985;
}
:is(button, [role="button"], .button-interaction, .landing-button):is(
  :disabled,
  [aria-disabled="true"],
  [aria-busy="true"]
) {
  scale: 1;
}

/* Radix keeps the dialog mounted briefly while its closing state animates. */
[data-slot="dialog-overlay"][data-state="open"] {
  animation: dialog-overlay-in 160ms ease-out both;
}
[data-slot="dialog-overlay"][data-state="closed"] {
  animation: dialog-overlay-out 120ms ease-in both;
}
[data-slot="dialog-content"][data-state="open"] {
  animation: dialog-content-in 180ms ease-out both;
}
[data-slot="dialog-content"][data-state="closed"] {
  animation: dialog-content-out 120ms ease-in both;
}
@keyframes dialog-overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes dialog-overlay-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes dialog-content-in {
  from {
    opacity: 0;
    scale: 0.985;
  }
  to {
    opacity: 1;
    scale: 1;
  }
}
@keyframes dialog-content-out {
  from {
    opacity: 1;
    scale: 1;
  }
  to {
    opacity: 0;
    scale: 0.985;
  }
}
@media (prefers-reduced-motion: reduce) {
  :is(button, [role="button"], .button-interaction, .landing-button) {
    scale: 1 !important;
  }
  [data-slot="dialog-overlay"],
  [data-slot="dialog-content"] {
    animation: none !important;
  }
}

/* Disabled text remains readable at the audit's requested 4.5:1 threshold. */
html[data-workspace] :is(button, input, select, textarea):disabled,
html[data-workspace] [aria-disabled="true"],
html[data-workspace] .recipient-header.opacity-60 {
  opacity: 1;
}

html[data-workspace][data-appearance="vercel"] .field-focus-wrapper,
html[data-workspace]
  :is(input:not([type="checkbox"]):not([type="radio"]), select, textarea):not(
    [aria-invalid="true"]
  ) {
  border-color: var(--input-boundary);
}

/* Shared by Premium notices, gated controls, and decorative examples. */
svg.premium-icon {
  color: var(--premium-icon);
  flex-shrink: 0;
}

